func TestB3MachineValidateRefusesDefinitionsThatIsNotUTF8(t *testing.T) {
	_, err := MachineValidate("\xff")
	if failure, ok := err.(*liberrors.FSMValueError); !ok || failure.Kind() != "invalid_text" {
		t.Fatalf("B-3: %#v", err)
	}
}

func TestB4MachineValidateValidateNotJson(t *testing.T) {
	_, err := MachineValidate("[")
	failure, ok := err.(*liberrors.FSMValueError)
	if !ok || failure.Kind() != "invalid_definition" {
		t.Fatalf("B-4: %#v", err)
	}
	if _, ok := failure.Status(); ok {
		t.Fatalf("B-4: the status of %#v", err)
	}
	if _, ok := failure.Errno(); ok {
		t.Fatalf("B-4: the errno of %#v", err)
	}
}

